import json
import httpx


from parser import apiOperations
from mcp.server import MCPServer
from mcp.types import Tool, CallToolResult, TextContent


# Create the MCP server
class OpenAPIServer(MCPServer):

    # Return the MCP tools generated by the parser
    async def list_tools(self):

        tools = []

        for operationInfo in apiOperations:

            tool = Tool(
                name=operationInfo["name"],
                title=operationInfo.get("title"),
                description=operationInfo.get("description"),
                inputSchema=operationInfo["inputSchema"],
                outputSchema=operationInfo.get("outputSchema")
            )

            tools.append(tool)

        return tools

    # Execute a tool requested by the MCP client
    async def call_tool(self, name, arguments, context=None):

        arguments = arguments or {}

        for operationInfo in apiOperations:

            if operationInfo["name"] == name:

                try:
                    result = await executeRequest(operationInfo, arguments)

                    return CallToolResult(
                        content=[
                            TextContent(
                                type="text",
                                text=json.dumps(result)
                            )
                        ]
                    )

                except httpx.HTTPStatusError as error:
                    return CallToolResult(
                        content=[
                            TextContent(
                                type="text",
                                text=(
                                    f"API error: HTTP {error.response.status_code} - "
                                    f"{error.response.text}"
                                )
                            )
                        ],
                        isError=True
                    )

                except httpx.RequestError as error:
                    return CallToolResult(
                        content=[
                            TextContent(
                                type="text",
                                text=f"Could not connect to API: {error}"
                            )
                        ],
                        isError=True
                    )

        raise ValueError(f"Unknown tool: {name}")


# Create the MCP server
mcp = OpenAPIServer("OpenAPI Tools")


# Send a request to the REST API
async def executeRequest(operationInfo, arguments):

    method = operationInfo["method"]
    path = operationInfo["path"]
    serverUrl = operationInfo["serverUrl"]

    queryParameters = {}
    requestBody = {}

    # Read the parameters from the OpenAPI operation
    for parameterName, parameterLocation in operationInfo["parameterLocations"].items():

        if parameterName not in arguments:
            continue

        parameterValue = arguments[parameterName]

        if parameterValue is None:
            continue

        if parameterLocation == "path":
            path = path.replace(
                "{" + parameterName + "}",
                str(parameterValue)
            )

        elif parameterLocation == "query":
            queryParameters[parameterName] = parameterValue

        elif parameterLocation == "body":
            requestBody[parameterName] = parameterValue

    # Combine the server URL and endpoint path
    url = serverUrl.rstrip("/") + "/" + path.lstrip("/")

    # Send the HTTP request
    async with httpx.AsyncClient(timeout=30.0) as client:

        response = await client.request(
            method=method.upper(),
            url=url,
            params=queryParameters,
            json=requestBody if "body" in operationInfo["parameterLocations"].values() else None
        )

        # Raise an error for unsuccessful HTTP responses
        response.raise_for_status()

        # Some endpoints return no response body
        if not response.content:
            return f"Request successful (HTTP {response.status_code})"

        # Return JSON if the API provides it
        try:
            return response.json()
        except ValueError:
            return response.text


# Run the MCP server
if __name__ == "__main__":
    mcp.run()
